function splitByDuration(samples, sr, segSec){
  if(!(sr>0)||!(segSec>0)||!samples||!samples.length) return [];
  var segLen=Math.max(1,Math.round(segSec*sr)), out=[];
  for(var i=0;i<samples.length;i+=segLen){ out.push(samples.slice(i,i+segLen)); }
  return out;
}
function findSilence(samples, sr, threshold, minSec){
  threshold=(threshold==null)?0.01:threshold; minSec=(minSec==null)?0.2:minSec;
  if(!(sr>0)||!samples) return [];
  var minN=Math.max(1,Math.floor(minSec*sr)), inSil=false, start=0, res=[];
  for(var i=0;i<samples.length;i++){ var s=Math.abs(samples[i])<threshold;
    if(s&&!inSil){ inSil=true; start=i; }
    else if(!s&&inSil){ if(i-start>=minN) res.push([start,i-1]); inSil=false; } }
  if(inSil && (samples.length-start)>=minN) res.push([start,samples.length-1]);
  return res;
}
var EXPORTS={splitByDuration:splitByDuration,findSilence:findSilence};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AudioSplitForgePure = EXPORTS; }
